CREATE TABLE "body_types" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "code" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idx_body_type_code" UNIQUE ("code"));
CREATE TABLE "brands" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "name" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idx_brands_name" UNIQUE ("name"));
CREATE TABLE "colors" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "code" text NOT NULL, "hex" text, PRIMARY KEY ("id"), CONSTRAINT "idx_colors_code" UNIQUE ("code"));
CREATE TABLE "drive_types" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "code" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idx_drive_type_code" UNIQUE ("code"));
CREATE TABLE "fuel_types" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "code" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idx_fuel_type_code" UNIQUE ("code"));
CREATE TABLE "models" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "name" text NOT NULL, "brand_id" uuid, PRIMARY KEY ("id"), CONSTRAINT "idx_models_name_brand" UNIQUE ("name", "brand_id"), FOREIGN KEY ("brand_id") REFERENCES "brands" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE "transmission_types" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "code" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idx_transmission_type_code" UNIQUE ("code"));
CREATE TABLE "cars" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "name" text NOT NULL, "description" text, "body_type_id" uuid, "power_hp" integer, "brand_id" uuid, "color_id" uuid, "drive_id" uuid, "fuel_id" uuid, "model_id" uuid, "transmission_id" uuid, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "deleted_at" timestamptz, PRIMARY KEY ("id"), FOREIGN KEY ("body_type_id") REFERENCES "body_types" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("brand_id") REFERENCES "brands" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("color_id") REFERENCES "colors" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("drive_id") REFERENCES "drive_types" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("fuel_id") REFERENCES "fuel_types" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("model_id") REFERENCES "models" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, FOREIGN KEY ("transmission_id") REFERENCES "transmission_types" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE "customers" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "first_name" text NOT NULL, "last_name" text, "phone" text, "email" text, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id"));
